/*
    This class illustrates how LAC context methods can be used generating PSAProjInvoice totals section.

    Current class has name postfixed with _Tutorial not to interfere with standard extensions. Rename class replacing _Tutorial with _Extension, modify a few
    places where class name is used, compile module, and on LAC parameters click "Clear cache" to refresh extension methods cache
*/
public static class LACTutorialPSAProjInvoice_Tutorial
{
}

Method.Source:
public static void LACPSAProjectDetailsTutorial(PSAProjInvoiceHeaderTmp _ProjInvoiceHeaderTmp, LACContext _context)
{
    XmlNode             detailNode, headingNode, subTotalNode, totalNode, transactionNode;
    XmlNode             projectGroupNode;
    PSAProjInvoiceTmp   pSAProjInvoiceTmp;
    ProjId              oldProjId;
    LanguageId          languageId;
    AmountMST           sumCategory, totalCategory;
    String20            oldTransTableLabel;
    ProjCategoryId      oldCategory;
    ProjInvoiceTable    projInvoiceTable;

    // Language used to the report
    ProjInvoiceTable    = ProjInvoiceTable::find(_ProjInvoiceHeaderTmp.ProjectContract);
    languageId = ProjInvoiceTable::getLanguageId(ProjInvoiceTable.ProjInvoiceProjId);

    detailNode      = _context.newSection('LACPSAProjInvoiceDetails');

    while select pSaProjInvoiceTmp
        order by pSaProjInvoiceTmp.ProjId
        where PSAProjInvoiceTmp.CreatedTransactionId == _ProjInvoiceHeaderTmp.CreatedTransactionId
    {
        if (PSAProjInvoiceTmp.ProjId != oldProjId)
        {
            // don't print subtotal and total for the category first time.
            if (oldProjId != "")
            {
                SubTotalNode    = _context.newSection('SubTotalForCategory', projectGroupNode);
                LACTutorialPSAProjInvoice_Tutorial::LACProjectSubtotalTutorial(sumCategory, LanguageId, SubTotalNode,_context);

                sumCategory = 0;
                oldCategory = "";

                TotalNode    = _context.newSection('TotalForTransTableLabel', projectGroupNode);
                LACTutorialPSAProjInvoice_Tutorial::LACProjectTotalTutorial(totalCategory, LanguageId, TotalNode,_context);

                totalCategory       = 0;
                oldTransTableLabel  = "";
            }


            headingNode     = _context.newSection('ProjectHeading',detailNode);
            LACTutorialPSAProjInvoice_Tutorial::LACProjectHeadingTutorial(PSAProjInvoiceTmp, languageId, headingNode, _context);
            projectGroupNode    = _context.newSection('ProjectGroup', headingNode);

            oldProjId = PSAProjInvoiceTmp.ProjId;
        }

        // Write subtotals and totals
        if (oldCategory && PSAProjInvoiceTmp.Category != oldCategory)
        {
            SubTotalNode    = _context.newSection('SubTotalForCategory',projectGroupNode);
            LACTutorialPSAProjInvoice_Tutorial::LACProjectSubtotalTutorial(sumCategory, LanguageId, SubTotalNode,_context);

            sumCategory = 0;
            oldCategory = PSAProjInvoiceTmp.Category;
        }
        // Write subtotals and totals
        if (oldTransTableLabel && PSAProjInvoiceTmp.TransTableLabel != oldTransTableLabel)
        {
            TotalNode    = _context.newSection('TotalForTransTableLabel',projectGroupNode);
            LACTutorialPSAProjInvoice_Tutorial::LACProjectTotalTutorial(totalCategory, LanguageId, TotalNode,_context);

            totalCategory = 0;
            oldTransTableLabel = PSAProjInvoiceTmp.TransTableLabel;
        }

        transactionNode = _context.newSection('Transactions', projectGroupNode);
        _context.newElement('FIELD_Category', pSaProjInvoiceTmp.Category, transactionNode);
        _context.newElement('FIELD_DescriptionForCategory', pSaProjInvoiceTmp.TransTxt, transactionNode);
        _context.newElement('FIELD_QuantityForCategory', pSaProjInvoiceTmp.Quantity, transactionNode);
        _context.newElement('FIELD_PriceForCategory', pSaProjInvoiceTmp.SalesPrice, transactionNode);
        _context.newElement('FIELD_AmountForCategory', pSaProjInvoiceTmp.LineAmount, transactionNode);
        _context.newElement('FIELD_TransTableLabel', pSaProjInvoiceTmp.TransTableLabel, transactionNode);
        _context.newElement('FIELD_PSAProjInvoiceTmpRecId', pSaProjInvoiceTmp.RecId, transactionNode);


        sumCategory         += PSAProjInvoiceTmp.LineAmount;
        totalCategory       += PSAProjInvoiceTmp.LineAmount;

        oldCategory         = PSAProjInvoiceTmp.Category;
        oldTransTableLabel  = PSAProjInvoiceTmp.TransTableLabel;

    }

    if (sumCategory)
    {
        SubTotalNode    = _context.newSection('SubTotalForCategory', projectGroupNode);
        LACTutorialPSAProjInvoice_Tutorial::LACProjectSubtotalTutorial(sumCategory, LanguageId, SubTotalNode,_context);
    }

    if (totalCategory)
    {
        TotalNode    = _context.newSection('TotalForTransTableLabel', projectGroupNode);
        LACTutorialPSAProjInvoice_Tutorial::LACProjectTotalTutorial(totalCategory, LanguageId, TotalNode,_context);
    }
}

private static void LACProjectHeadingTutorial(PSAProjInvoiceTmp _pSAProjInvoiceTmp, LanguageId  _languageId, XMLNode _node, LACContext _context)
{
    _context.newElement('LABEL_ProjectName', SysLabel::labelId2String2(literalStr("@SYS15760"), _languageId), _node);
    _context.newElement('LABEL_ProjectID', SysLabel::labelId2String2(literalStr("@SYS103748"), _languageId), _node);
    _context.newElement('LABEL_Category', SysLabel::labelId2String2(literalStr("@SYS81431"), _languageId), _node);
    _context.newElement('LABEL_Description', SysLabel::labelId2String2(literalStr("@SYS6303"), _languageId), _node);
    _context.newElement('LABEL_Quantity', SysLabel::labelId2String2(literalStr("@SYS3065"), _languageId), _node);
    _context.newElement('LABEL_Price', SysLabel::labelId2String2(literalStr("@SYS11865"), _languageId), _node);
    _context.newElement('LABEL_Amount', SysLabel::labelId2String2(literalStr("@SYS6928"), _languageId), _node);
    _context.newElement('FIELD_ProjectName', _pSAProjInvoiceTmp.ProjectName, _node);
    _context.newElement('FIELD_ProjectID', _pSAProjInvoiceTmp.ProjId, _node);
}

private static void LACProjectSubtotalTutorial(AmountMST _subtotal, LanguageId  _languageId, XMLNode _node, LACContext _context)
{
    _context.newElement('LABEL_SubTotal', SysLabel::labelId2String2(literalStr("@sys7470"), _languageId), _node);
    _context.newElement('FIELD_SubTotal', _subtotal, _node);
}

private static void LACProjectTotalTutorial(AmountMST _subtotal, LanguageId  _languageId, XMLNode _node, LACContext _context)
{
    _context.newElement('LABEL_TotalForCategory', SysLabel::labelId2String2(literalStr("@SYS809"), _languageId), _node);
    _context.newElement('FIELD_TotalForCategory', _subtotal, _node);
}

/// <summary>
/// Method calculates Project proposal or Invoice line tax amount for the Project Invoice report (PSAProjInvoiceReplacement)
/// </summary>
/// <param name = "_psaProjInvoiceTmp">PSA invoice or proforma line</param>
/// <param name = "_context">LAC context object from LAC report run</param>
/// <returns>Tax amount calculated for the Project proposale line</returns>
public static TaxAmountCur LACPSAProjInvoiceLineTaxAmountTutorial(PSAProjInvoiceTmp _psaProjInvoiceTmp, LACContext _context)
{
    TaxAmountCur    lineTaxAmount;
    Common          projInvoiceLineOrig;

    Tax             tax;

    projInvoiceLineOrig = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTmp_GetLineOrigTutorial(_psaProjInvoiceTmp);
    switch (projInvoiceLineOrig.TableId)
    {
        case tableNum(projProposalEmpl):
        case tableNum(ProjProposalCost):
        case tableNum(projProposalItem):
        case tableNum(projProposalRevenue):
        case tableNum(projProposalOnAcc):
            tax = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTmp_GetTaxTutorial(_psaProjInvoiceTmp);
            if (tax)
            {
                projInvoiceLineOrig = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTmp_GetLineOrigTutorial(_psaProjInvoiceTmp);
                lineTaxAmount = tax.totalTaxAmountSingleLine(projInvoiceLineOrig.TableId, projInvoiceLineOrig.RecId);
            }
            break;
        case tableNum(projInvoiceEmpl):
        case tableNum(ProjInvoiceCost):
        case tableNum(projInvoiceItem):
        case tableNum(projInvoiceRevenue):
        case tableNum(projInvoiceOnAcc):
            lineTaxAmount = projInvoiceLineOrig.(fieldName2Id(projInvoiceLineOrig.TableId, 'TaxAmount'));
            break;
    }
    return lineTaxAmount;
}

/// <summary>
///  Builds section for the report Invoice Revenue line with tax information
/// </summary>
/// <param name = "_projInvoiceRevenueDetail">Invoice revenue line details</param>
/// <param name = "_context">LAC context object from LAC report run</param>
public static void LACProjInvoiceRevenueTaxTutorial(ProjInvoiceRevenueDetail _projInvoiceRevenueDetail, LACContext _context)
{
    TaxTrans            taxTrans;
    XmlNode detailNode, sectionNode = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTaxHeadingTutorial(_context);
    while select taxTrans
        where taxTrans.SourceTableId == tableNum(ProjInvoiceRevenue) &&
                taxTrans.SourceRecId ==   _projInvoiceRevenueDetail.InvoiceRefRecId &&
                taxTrans.TaxDirection != TaxDirection::UseTax &&
                taxTrans.TaxOrigin != TaxOrigin::TaxReversed
    {
        detailNode = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTaxDetailTutorial(
                        _context,
                        sectionNode,
                        taxTrans.TaxCode,
                        taxTrans.TaxBaseQty * -1,
                        taxTrans.TaxBaseAmountCur * -1,
                        taxTrans.TaxValue,
                        taxTrans.SourceRegulateAmountCur * -1,
                        taxTrans.TaxDirection);
    }
}

/// <summary>
///  Builds section for the report with Project proposal or Invoice line tax information for the Project Invoice report (PSAProjInvoiceReplacement)
/// </summary>
/// <param name = "_psaProjInvoiceTmp">PSA invoice or proforma line</param>
/// <param name = "_context">LAC context object from LAC report run</param>
public static void LACPSAProjInvoiceLineTaxTutorial(PSAProjInvoiceTmp _psaProjInvoiceTmp, LACContext _context)
{
    Common              projInvoiceLineOrig;
    projInvoiceLineOrig = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTmp_GetLineOrigTutorial(_psaProjInvoiceTmp);
    TaxTrans            taxTrans;

    switch (projInvoiceLineOrig.TableId)
    {
        case tableNum(projProposalEmpl):
        case tableNum(ProjProposalCost):
        case tableNum(projProposalItem):
        case tableNum(projProposalRevenue):
        case tableNum(projProposalOnAcc):
            Tax             tax;
            tax = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTmp_GetTaxTutorial(_psaProjInvoiceTmp);
            if (tax)
            {
                TmpTaxWorkTrans     taxWorkTrans;
                taxWorkTrans =      tax.tmpTaxWorkTrans();

                XmlNode detailNode, sectionNode = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTaxHeadingTutorial(_context);

                while select taxWorkTrans
                    where (taxWorkTrans.SourceTableId == projInvoiceLineOrig.tableID &&
                    taxWorkTrans.SourceRecId == projInvoiceLineOrig.RecId) ||
                    (taxWorkTrans.ParentSourceTableId == projInvoiceLineOrig.TableID &&
                    taxWorkTrans.ParentSourceRecId == projInvoiceLineOrig.RecID) &&
                (taxWorkTrans.TaxDirection     != TaxDirection::UseTax) &&
                taxWorkTrans.TaxOrigin        != TaxOrigin::TaxReversed
                {
                    detailNode = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTaxDetailTutorial(
                        _context,
                        sectionNode,
                        taxWorkTrans.TaxCode,
                        taxWorkTrans.TaxBaseQty * -1,
                        taxWorkTrans.TaxBaseAmountCur * -1,
                        taxWorkTrans.showTaxValue(),
                        taxWorkTrans.SourceRegulateAmountCur * -1,
                        taxWorkTrans.TaxDirection);
                }
            }
            break;
        case tableNum(projInvoiceEmpl):
        case tableNum(ProjInvoiceCost):
        case tableNum(projInvoiceItem):
        case tableNum(projInvoiceRevenue):
        case tableNum(projInvoiceOnAcc):

            XmlNode detailNode, sectionNode = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTaxHeadingTutorial(_context);
            while select taxTrans
                where taxTrans.SourceTableId == projInvoiceLineOrig.tableID &&
                      taxTrans.SourceRecId ==   projInvoiceLineOrig.RecId &&
                      taxTrans.TaxDirection != TaxDirection::UseTax &&
                      taxTrans.TaxOrigin != TaxOrigin::TaxReversed
            {
                detailNode = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTaxDetailTutorial(
                        _context,
                        sectionNode,
                        taxTrans.TaxCode,
                        taxTrans.TaxBaseQty * -1,
                        taxTrans.TaxBaseAmountCur * -1,
                        taxTrans.TaxValue,
                        taxTrans.SourceRegulateAmountCur * -1,
                        taxTrans.TaxDirection);
            }
            break;
    }
}

/// <summary>
/// Returns Corresponding Proposal or invoice line record
/// </summary>
/// <param name = "_psaProjInvoiceTmp">Temporary table used as a buffer for lines in the Report</param>
/// <returns>Corresponding Proposal or invoice line record</returns>
private static common LACPSAProjInvoiceLineTmp_GetLineOrigTutorial(PSAProjInvoiceTmp _psaProjInvoiceTmp)
{
    ProjProposalEmpl            projProposalEmpl;
    ProjProposalCost            projProposalCost;
    ProjProposalItem            projProposalItem;
    ProjProposalRevenue         projProposalRevenue;
    ProjProposalOnAcc           projProposalOnAcc;
    Common                      projInvoiceLine;

    if (_psaProjInvoiceTmp.LACProposalTransRefRecId)
    {
        switch(_psaProjInvoiceTmp.LACProjTransType)
        {
            case ProjTransType::Hour:
                projProposalEmpl = projProposalEmpl::findRecId(_psaProjInvoiceTmp.LACProposalTransRefRecId);
                if (projProposalEmpl.RecId && projProposalEmpl.TaxGroupId && projProposalEmpl.TaxItemGroupId)
                {
                    return projProposalEmpl;
                }
                break;
            case ProjTransType::Cost:
                projProposalCost = ProjProposalCost::findRecId(_psaProjInvoiceTmp.LACProposalTransRefRecId);
                if (projProposalCost.RecId && projProposalCost.TaxGroupId && projProposalCost.TaxItemGroupId)
                {
                    return projProposalCost;
                }
                break;
            case ProjTransType::Item:
                projProposalItem = projProposalItem::findRecId(_psaProjInvoiceTmp.LACProposalTransRefRecId);
                if (projProposalItem.RecId && projProposalItem.TaxGroupId && projProposalItem.TaxItemGroupId)
                {
                    return projProposalItem;
                }
                break;
            case ProjTransType::Revenue:
                projProposalRevenue = projProposalRevenue::findRecId(_psaProjInvoiceTmp.LACProposalTransRefRecId);
                if (projProposalRevenue.RecId && projProposalRevenue.TaxGroupId && projProposalRevenue.TaxItemGroupId)
                {
                    return projProposalRevenue;
                }
                break;
            case ProjTransType::OnAccount:
                projProposalOnAcc = projProposalOnAcc::findRecId(_psaProjInvoiceTmp.LACProposalTransRefRecId);
                if (projProposalOnAcc.RecId && projProposalOnAcc.TaxGroupId && projProposalOnAcc.TaxItemGroupId)
                {
                    return projProposalOnAcc;
                }
                break;
        }
    }
    if (_psaProjInvoiceTmp.LACTransRefRecId)
    {
        switch(_psaProjInvoiceTmp.LACProjTransType)
        {
            case ProjTransType::Hour:
                return projInvoiceEmpl::findRecId(_psaProjInvoiceTmp.LACTransRefRecId);
                break;
            case ProjTransType::Cost:
                return ProjInvoiceCost::findRecId(_psaProjInvoiceTmp.LACTransRefRecId);
                break;
            case ProjTransType::Item:
                return projInvoiceItem::findRecId(_psaProjInvoiceTmp.LACTransRefRecId);
                break;
            case ProjTransType::Revenue:
                return projInvoiceRevenue::findRecId(_psaProjInvoiceTmp.LACTransRefRecId);
                break;
            case ProjTransType::OnAccount:
                return projInvoiceOnAcc::findRecId(_psaProjInvoiceTmp.LACTransRefRecId);
                break;
        }
    }
    return  projInvoiceLine;
}

/// <summary>
/// Returns Tax object used to calculate Taxes for Proposal lines (line level)
/// </summary>
/// <param name = "_psaProjInvoiceTmp">Temporary table used as a buffer for lines in the Report</param>
/// <returns>Tax object</returns>
private static Tax LACPSAProjInvoiceLineTmp_GetTaxTutorial(PSAProjInvoiceTmp _psaProjInvoiceTmp)
{
    Common                      projInvoiceLineOrig;
    ProjProposalJour            projProposalJour;
    Tax                         tax;


    projInvoiceLineOrig = LACTutorialPSAProjInvoice_Tutorial::LACPSAProjInvoiceLineTmp_GetLineOrigTutorial(_psaProjInvoiceTmp);

    if (projInvoiceLineOrig.RecId)
    {
        switch(projInvoiceLineOrig.tableId)
        {
            case tableNum(projProposalEmpl):
                projProposalJour = projProposalEmpl::findRecId(projInvoiceLineOrig.RecId).projProposalJour();
                break;
            case tableNum(ProjProposalCost):
                projProposalJour = ProjProposalCost::findRecId(projInvoiceLineOrig.RecId).projProposalJour();
                break;
            case tableNum(projProposalItem):
                projProposalJour = projProposalItem::findRecId(projInvoiceLineOrig.RecId).projProposalJour();
                break;
            case tableNum(projProposalRevenue):
                projProposalJour = projProposalRevenue::findRecId(projInvoiceLineOrig.RecId).projProposalJour();
                break;
            case tableNum(projProposalOnAcc):
                projProposalJour = projProposalOnAcc::findRecId(projInvoiceLineOrig.RecId).projProposalJour();
                break;
        }
    }

    if (projInvoiceLineOrig && projProposalJour)
    {
        ProjProposalTotals  projProposalTotals;
        TmpTaxWorkTrans     taxWorkTrans;
        projProposalTotals = new projProposalTotals(projProposalJour);

        projProposalTotals.calc();
        tax = projProposalTotals.tax();
        tax.sourceSingleLine(true, true);
    }
    return tax;

}

/// <summary>
///  Returns XML Header for the line tax details section
/// </summary>
/// <param name = "_context">Lasernet report context object</param>
/// <returns>XML node to be used in the report</returns>
private static XMLNode LACPSAProjInvoiceLineTaxHeadingTutorial(LACContext _context)
{
    LanguageId          languageId = _context.parmReportContractData().parmLanguageId();
    XmlNode sectionNode = _context.newSection("LACPSAInvoiceLineTaxTmp");

    _context.newLabel('Label_TaxCode', SysLabel::labelId2String2(literalStr("@SYS21877"), languageId), sectionNode);
    _context.newLabel('Label_TaxBaseQty', SysLabel::labelId2String2(literalStr("@SYS14578"), languageId), sectionNode);
    _context.newLabel('Label_TaxBaseAmountCur', SysLabel::labelId2String2(literalStr("@SYS21950"), languageId), sectionNode);
    _context.newLabel('Label_TaxValuePct', SysLabel::labelId2String2(literalStr("@SYS15774"), languageId), sectionNode);
    _context.newLabel('Label_TaxRegulateAmountCur', SysLabel::labelId2String2(literalStr("@SYS128972"), languageId), sectionNode);
    _context.newLabel('Label_TaxDirection', SysLabel::labelId2String2(literalStr("@SYS23179"), languageId), sectionNode);

    return sectionNode;
}

/// <summary>
/// Returns XML data for the line tax details section
/// </summary>
/// <param name = "_context">Lasernet report context object</param>
/// <param name = "_sectionNode">XML node</param>
/// <param name = "_taxCode">Tax code</param>
/// <param name = "_taxBaseQty">Tax base quantity</param>
/// <param name = "_taxBaseAmountCur">Tax base amount</param>
/// <param name = "_taxValuePct">Tax value</param>
/// <param name = "_taxRegulateAmountCur">Tax amount</param>
/// <param name = "_taxDirection">Tax direction</param>
/// <returns>XML node to be used in the report</returns>
private static XMLNode LACPSAProjInvoiceLineTaxDetailTutorial(
    LACContext      _context,
    XMLNode         _sectionNode,
    TaxCode         _taxCode,
    SalesQty        _taxBaseQty,
    TaxAmountCur    _taxBaseAmountCur,
    Percent         _taxValuePct,
    TaxAmountCur    _taxRegulateAmountCur,
    TaxDirection    _taxDirection)
{
    XmlNode detailNode = _context.newSection("LACPSAInvoiceLineTaxTmpDetails", _sectionNode);
    _context.newElement("TaxCode", _taxCode, detailNode);
    _context.newElement("TaxBaseQty", _taxBaseQty, detailNode, extendedTypeNum(SalesQty));
    _context.newElement("TaxBaseAmountCur", _taxBaseAmountCur, detailNode, extendedTypeNum(TaxAmountCur));
    _context.newElement("TaxValuePct", _taxValuePct, detailNode);
    _context.newElement("TaxRegulateAmountCur", _taxRegulateAmountCur, detailNode, extendedTypeNum(TaxAmountCur));
    _context.newElement("TaxDirection", _taxDirection, detailNode);
    return detailNode;
}
